func TestPruneSkipsActiveMarker(t *testing.T) {
	c := newTestCache(t)
	s := testSource("locked", time.Hour, 30*time.Second)
	dir := filepath.Join(c.Root, s.Tier)
	if err := os.MkdirAll(dir, 0o750); err != nil {
		t.Fatal(err)
	}
	if err := atomicWrite(c.dataPath(s), []byte(`{}`)); err != nil {
		t.Fatal(err)
	}
	m := &refreshMarker{
		PID:       os.Getpid(),
		StartedAt: time.Now().UTC(),
		Deadline:  time.Now().UTC().Add(30 * time.Second),
	}
	if err := writeMarker(c.markerPath(s), m); err != nil {
		t.Fatal(err)
	}

	if err := c.Prune(nil); err != nil {
		t.Fatal(err)
	}

	if _, err := os.Stat(c.dataPath(s)); os.IsNotExist(err) {
		t.Error("Prune removed data file of actively-refreshing source")
	}
}

	stop := make(chan struct{})
	errs := make(chan string, numReaders*10)
	var wg sync.WaitGroup

	for range numReaders {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for {
				select {
				case <-stop:
					return
				default:
				}
				data, err := os.ReadFile(c.dataPath(s))
				if err != nil {
					continue
				}
				if !valid[string(data)] {
					errs <- fmt.Sprintf("invalid/torn payload len=%d: %.80s", len(data), data)
				}
			}
		}()
	}

	for i := 1; i < numVersions; i++ {
		if err := atomicWrite(c.dataPath(s), payloads[i]); err != nil {
			close(stop)
			t.Fatal(err)
		}
	}

	close(stop)
	wg.Wait()
	close(errs)

	for e := range errs {
		t.Error(e)
	}
}

