	s := Source{Tier: "discovery", Name: "active-during-prune", TTL: time.Hour, RefreshDeadline: 60 * time.Second}
	_ = os.MkdirAll(filepath.Join(c.Root, s.Tier), 0o750)

	if err := atomicWrite(c.dataPath(s), []byte(`{"preserved":true}`)); err != nil {
		t.Fatal(err)
