	m := &refreshMarker{
		PID:       os.Getpid(),
		StartedAt: time.Now().UTC(),
		Deadline:  time.Now().UTC().Add(60 * time.Second),
	}
	if err := writeMarker(c.markerPath(s), m); err != nil {
		t.Fatal(err)
	}

